<script setup lang="ts">
import {ref,computed} from 'vue'
import {iou,crossEntropy,regressionLoss} from '../utils/learningMath'
const x=ref(175),y=ref(91),width=ref(112),score=ref(1.5),target=[150,100,130,88]
const predicted=computed(()=>[x.value,y.value,width.value,88]),overlap=computed(()=>iou(target,predicted.value)),ce=computed(()=>crossEntropy([score.value,0],0)),loc=computed(()=>predicted.value.reduce((s,v,i)=>s+regressionLoss((v-target[i])/100,'huber').loss,0))
</script>
<template><div class="lab-grid"><svg class="lab-svg" viewBox="0 0 510 265" role="img" aria-label="Boîte vraie et boîte prédite"><rect x="15" y="15" width="480" height="225" fill="#ddebf0"/><path d="M180 85L80 240H465L295 85Z" fill="#64748b"/><path d="M245 95L260 240" stroke="white" stroke-dasharray="15 12" stroke-width="4"/><rect x="35" y="40" width="110" height="105" fill="#adc1ca"/><rect x="355" y="30" width="100" height="110" fill="#c8d5d9"/><rect x="158" y="115" width="112" height="61" rx="12" fill="#b33537"/><rect x="179" y="122" width="64" height="24" rx="4" fill="#a7dbe9"/><circle cx="179" cy="178" r="10" fill="#333"/><circle cx="250" cy="178" r="10" fill="#333"/><rect x="150" y="100" width="130" height="88" fill="none" stroke="#25B34B" stroke-width="3"/><rect :x="x" :y="y" :width="width" height="88" fill="none" stroke="#CF1C24" stroke-width="3" stroke-dasharray="7 3"/><text x="24" y="257" style="fill:#218638">Vert : annotation</text><text x="260" y="257" style="fill:#CF1C24">Rouge : prédiction</text></svg><div class="lab-readout" data-testid="detection"><p>Classe cible : <b>voiture</b></p><p>p(voiture) = {{ce.p[0].toFixed(3)}}</p><p>Intersection / union :<br/><strong>IoU = {{overlap.toFixed(3)}}</strong></p><p>ℓclasse = {{ce.loss.toFixed(3)}}<br/>ℓboîte = {{loc.toFixed(3)}}</p><p>Somme illustrative : <b>{{(ce.loss+loc).toFixed(3)}}</b></p></div></div><div class="lab-controls"><label>x<input aria-label="Boîte x" v-model.number="x" type="range" min="60" max="270"/></label><label>y<input aria-label="Boîte y" v-model.number="y" type="range" min="40" max="140"/></label><label>Largeur<input aria-label="Largeur boîte" v-model.number="width" type="range" min="50" max="170"/></label><label>Score<input aria-label="Score voiture" v-model.number="score" type="range" min="-3" max="4" step=".1"/></label></div></template>
